celestial_give_treasury_interaction.original_accept_body:
scope:actor = {
	# Let the player know they won't get additional opinion
	if = {
		limit = {
			scope:recipient = {
				has_opinion_modifier = {
					target = scope:actor
					modifier = treasury_gift_opinion
				}
			}
		}
		custom_tooltip = ALREADY_SENT_TREASURY_WARNING
	}
	send_interface_toast = {
		type = event_toast_effect_good
		title = celestial_give_treasury_interaction
		right_icon = scope:recipient

		# Transfer treasury amount
		pay_short_term_treasury = {
			target = scope:recipient
			treasury = give_treasury_value
		}

		# Advancement movement members get merit when in the advancement phase
		if = {
			limit = {
				top_participant_group:dynastic_cycle ?= {
					has_participant_group_parameter = dynastic_cycle_send_treasury_for_merit
				}
			}
			change_merit = medium_merit_value
		}

		if = {
			limit = { government_has_flag = government_has_influence }
			change_influence = medium_influence_value
		}

		scope:recipient = {
			# They will like actor for it
			add_opinion = {
				target = scope:actor
				modifier = treasury_gift_opinion
				opinion = 20
			}
		}
	}
}

celestial_demand_treasury_interaction.original_accept_body:
# Save the recipients current treasury, to make sure it doesn't change
save_scope_value_as = {
	name = recipient_treasury_amount
	value = { # We take half their treasury, up to a maximum based on tier
		value = scope:recipient.treasury
		multiply = 0.5
		max = {
			value = 400
			multiply = scope:recipient.primary_title.tier
		}
	}
}
scope:actor = {
	send_interface_toast = {
		type = event_toast_effect_good
		title = celestial_demand_treasury_interaction
		right_icon = scope:recipient

		scope:recipient = {
			# Pay half the treasury to actor
			pay_short_term_treasury = {
				target = scope:actor
				treasury = scope:recipient_treasury_amount
			}
		}
	}
}

pay_treasury_debt_interaction.original_accept_body:
scope:actor = {
	pay_short_term_treasury	= {
		target = scope:recipient
		treasury = {
			value = scope:recipient.treasury
			multiply = -1
		}
	}
	if = {
		limit = {
			scope:strong_hook = yes
		}
		add_hook = {
			type = strong_indebted_hook
			target = scope:recipient
		}
	}
	if = {
		limit = {
			scope:weak_hook = yes
		}
		add_hook = {
			type = indebted_hook
			target = scope:recipient
		}
	}
	if = {
		limit = {
			scope:kindness = yes
		}
		scope:recipient = {
			progress_towards_friend_effect = {
				REASON = friend_paid_debt
				CHARACTER = scope:actor
				OPINION = default_friend_opinion
			}
		}
	}
	change_influence = major_influence_value
}
situation:dynastic_cycle ?= {
	if = {
		limit = {
			situation_top_has_catalyst = catalyst_cleared_treasury_debt
			any_situation_participant = {
				this = scope:recipient
			}
		}
		trigger_situation_catalyst = {
			catalyst = catalyst_cleared_treasury_debt
			character = scope:actor
		}
	}
}
